// Independent, deliberately applied search states; no search results on first visit.
const filterDefaults=()=>({query:'',company:'',title:'',country:'',county:'',location:'',size:'',medicine:'',industry:'',keywords:''});
const searchStates={};
let discoveryMode='discover',returnSaved=false,savedEntities={people:[],companies:[]},savedStorageAvailable=true;
const savedKey='infoxem-saved-entities-v1';
try{const store=JSON.parse(localStorage.getItem(savedKey)||'null');if(store&&Array.isArray(store.people)&&Array.isArray(store.companies))savedEntities={people:[...new Set(store.people)].filter(id=>directory.some(c=>c.employees.some(p=>p.id===id))),companies:[...new Set(store.companies)].filter(id=>directory.some(c=>c.id===id))}}catch(e){savedStorageAvailable=false}
const companySizes=[['1','Self-employed'],['1-10','1–10 employees'],['11-50','11–50 employees'],['51-200','51–200 employees'],['201-500','201–500 employees'],['501-1000','501–1,000 employees'],['1001-5000','1,001–5,000 employees'],['5001-10000','5,001–10,000 employees'],['10001+','10,001+ employees']];
const fixtureHeadcounts=[145,65,8,350,24,1,780,1250,6,5500,43,12000];
directory.forEach((c,i)=>{c.headcount=fixtureHeadcounts[i];c.sizeLabel=companySizes.find(([v])=>sizeMatches(c.headcount,v))?.[1]||'Unknown';c.industry=c.type==='Retailer'?'Retail Pharmacies':i%3===1?'Medical Distribution':'Pharmaceuticals';c.keywords=[c.type,c.industry,'healthcare','distribution','pharmaceuticals',c.type==='Retailer'?'community pharmacy':'export partners',...c.medicines].join(' ');c.employees.forEach((p,n)=>{p.country=c.country;p.county=c.county;p.city=c.city;p.skills=n===0?'procurement, purchasing, supplier management':n===1?'business development, leadership, partnerships':'sales, business development, account management';p.bio=`${p.role} working in ${c.industry}. ${p.skills}.`})});
document.querySelector('svg defs').insertAdjacentHTML('beforeend',`<symbol id="i-bookmark" viewBox="0 0 24 24"><path d="M6 3h12v18l-6-4-6 4V3Z"/></symbol><symbol id="i-filter" viewBox="0 0 24 24"><path d="M3 6h18M6 12h12M9 18h6"/><circle cx="8" cy="6" r="2" fill="white"/><circle cx="15" cy="12" r="2" fill="white"/></symbol><symbol id="i-briefcase" viewBox="0 0 24 24"><rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12c5 4 13 4 18 0M10 13h4"/></symbol>`);
function sizeMatches(n,range){if(!range)return true;if(range==='1')return n===1;if(range==='10001+')return n>=10001;const [min,max]=range.split('-').map(Number);return n>=min&&n<=max}
function currentSearch(){const key=leadPage+':'+discoveryMode;return searchStates[key]??=( {draft:filterDefaults(),applied:filterDefaults(),searched:false,sort:'relevance',page:0,type:'all',error:''} )}
function filterKeys(){return leadPage==='people'?['query','company','title','country','county','location','industry','keywords']:['query','company','country','county','location','size','medicine','industry','keywords']}
function filterCount(f){const keys=filterKeys();let count=keys.filter(k=>!['county','location'].includes(k)&&f[k]?.trim()).length;if(!f.country&&(f.county||f.location))count++;return count}
function filterChanges(s){return filterKeys().some(k=>s.draft[k]!==s.applied[k])}
function activeFilters(f){const labels={query:'Search',company:'Company',title:'Job title',country:'Country',county:'County',location:'City / region',size:'Company size',medicine:'Medicine',industry:'Industry',keywords:'Keywords'};return filterKeys().filter(k=>f[k]?.trim()).map(k=>[labels[k],k==='size'?(companySizes.find(([v])=>v===f[k])?.[1]||f[k]):f[k]])}
function splitTerms(v){return String(v||'').toLowerCase().split(/[,;]+/).map(x=>x.trim()).filter(Boolean)}
function matchesAny(text,v){return !v||splitTerms(v).some(term=>text.toLowerCase().includes(term))}


function queryCountries(query){return [...new Set(directory.map(c=>c.country))].filter(c=>new RegExp('\\b'+c.toLowerCase()+'\\b').test((query||'').toLowerCase()))}
function effectiveCountyCountry(f){const countries=queryCountries(f.query);return f.country||(countries.length===1?countries[0]:'')}
function syncCountyPicker(){const s=currentSearch(),country=effectiveCountyCountry(s.draft),picker=$('#filter-county');if(!picker)return;const options=countyOptions(country);if(!options.includes(s.draft.county))s.draft.county='';picker.disabled=country!=='Kenya';picker.innerHTML='<option value="">'+(country==='Kenya'?'Any county':'County · select Kenya')+'</option>'+options.map(c=>'<option '+(s.draft.county===c?'selected':'')+'>'+c+'</option>').join('')}

/* USER-JOURNEY
 * WHAT A PRODUCT OR COUNTRY SEARCH MEANS TO THE USER
 * A country search narrows the market; a product search narrows relevant companies.
 * A combined search narrows by both. People results use the employer's product categories
 * and the person's location; they do not imply medical expertise or qualifications.
 * The mockup covers only a small fictional set of products and countries.
 */
function quickQueryMatches(company,person,query){
  if(!query||!query.trim())return true;
  const countries=[...new Set(directory.map(c=>c.country))];
  const chosen=[];
  let products=query.toLowerCase();
  countries.forEach(country=>{const expression=new RegExp('\\b'+country.toLowerCase()+'\\b','g');if(expression.test(products)){chosen.push(country);products=products.replace(expression,' ')}});
  if(chosen.length&&!chosen.includes(person?person.country:company.country))return false;
  const terms=products.split(/[,;]|\s+(?:and|or|in)\s+/).map(v=>v.trim().replace(/^(?:in|and|or)\s+|\s+(?:in|and|or)$/g,'').trim()).filter(Boolean).map(t=>t==='acetaminophen'?'paracetamol':/anti[ -]?malarial/.test(t)?'antimalarial drugs':t);
  return !terms.length||terms.some(t=>company.medicines.some(m=>m.toLowerCase().includes(t)));
}
/* USER-JOURNEY
 * SEARCH BAR: BEGIN WITH A PRODUCT OR MARKET
 * Users enter searches such as Kenya, Paracetamol, or Paracetamol in Kenya.
 * They select Search or press Enter to see results. Typing alone does not change the list.
 * On People, medicine searches find employees at companies associated with those products.
 * On the Saved tab, the same search looks only within the user's saved records.
 */
function quickSearchBar(){const s=currentSearch(),people=leadPage==='people';return `<!-- FEATURE: primary medicine/product/country search -->
<section class="primary-search-panel" aria-label="Primary search">
  <form id="quick-search-form" class="primary-search-form">
    <div class="primary-search-input"><label for="quick-search">Search by medicine, product category, or country</label><div class="primary-search-control">${icon('search')}<input id="quick-search" type="search" class="input" value="${esc(s.draft.query)}" placeholder="e.g. Paracetamol in Kenya" autocomplete="off" aria-describedby="quick-search-hint"></div></div>
    <button type="submit" class="btn primary" aria-label="Search ${people?'people':'companies'}">${icon('search')}Search</button>
  </form>
  <div class="primary-search-hint" id="quick-search-hint">${icon('info')}${people?'Medicine searches find people at companies dealing with those products. Add job title, company, or location filters below.':'Search a medicine, a product category, or a country. Then use the filters below to refine your results.'}</div>
  <p class="filter-validation" id="quick-search-error" role="alert">${esc(s.error)}</p>
</section>`}
function wireQuickSearch(){
  $('#quick-search').addEventListener('input',e=>{const s=currentSearch();s.draft.query=e.target.value;syncCountyPicker();s.error='';$('#quick-search-error').textContent='';$('#filter-validation').textContent='';updateFilterStatus()});
  $('#quick-search-form').addEventListener('submit',e=>{e.preventDefault();applyDiscoveryFilters()});
}

function companyMatches(c,f){if(!quickQueryMatches(c,null,f.query))return false;if(!matchesAny(c.name+' '+c.website,f.company))return false;if(f.country&&c.country!==f.country)return false;if(f.county&&c.county!==f.county)return false;if(!matchesAny([c.city,c.county,c.country].join(' '),f.location))return false;if(f.industry&&c.industry!==f.industry)return false;if(!sizeMatches(c.headcount,f.size))return false;if(f.medicine){const terms=splitTerms(f.medicine).map(t=>t==='acetaminophen'?'paracetamol':/anti[ -]?malarial/.test(t)?'antimalarial drugs':t);if(!terms.some(t=>c.medicines.some(m=>m.toLowerCase().includes(t))))return false}return matchesAny(c.keywords+' '+c.name,f.keywords)}
function personMatches(c,p,f){return quickQueryMatches(c,p,f.query)&&matchesAny(c.name+' '+c.website,f.company)&&matchesAny(p.role,f.title)&&(!f.country||p.country===f.country)&&(!f.county||p.county===f.county)&&matchesAny([p.city,p.county,p.country].join(' '),f.location)&&(!f.industry||c.industry===f.industry)&&matchesAny([p.name,p.role,p.skills,p.bio].join(' '),f.keywords)}
function searchRecords(){const s=currentSearch(),f=s.applied;if(discoveryMode==='discover'&&!s.searched)return [];let records=leadPage==='people'?directory.flatMap(c=>c.employees.map(p=>({c,p}))):[...directory];if(discoveryMode==='saved')records=records.filter(r=>savedEntities[leadPage].includes(leadPage==='people'?r.p.id:r.id));if(s.searched)records=records.filter(r=>leadPage==='people'?personMatches(r.c,r.p,f):companyMatches(r,f));if(s.type!=='all')records=records.filter(r=>(leadPage==='people'?r.c:r).type===s.type);if(s.sort==='name')records.sort((a,b)=>(leadPage==='people'?a.p.name:a.name).localeCompare(leadPage==='people'?b.p.name:b.name));if(s.sort==='company')records.sort((a,b)=>(a.c?.name||a.name).localeCompare(b.c?.name||b.name));if(s.sort==='size')records.sort((a,b)=>b.headcount-a.headcount);return records}
function directoryNav(){document.querySelector('.sidebar nav').innerHTML="<button class=\"nav-item\" id=\"nav-home\" data-lead-nav=\"home\">"+icon('home')+"<span class=\"nav-text\">Home</span></button><div class=\"nav-section-label\">MARKET RESEARCH</div>"+"<button class=\"nav-item nav-parent\" id=\"nav-find\" aria-expanded=\"true\" aria-controls=\"find-leads-nav\">"+icon('search')+"<span class=\"nav-text\">Find Leads</span>"+icon('chevron','nav-chevron')+"</button><div class=\"nav-sub\" id=\"find-leads-nav\"><button class=\"nav-item\" id=\"nav-people\" data-lead-nav=\"people\">"+icon('people')+"<span class=\"nav-text\">People</span></button><button class=\"nav-item\" id=\"nav-companies\" data-lead-nav=\"companies\">"+icon('building')+"<span class=\"nav-text\">Companies</span></button></div><div class=\"nav-separator\"></div><div class=\"nav-section-label\">ENRICHMENT</div><button class=\"nav-item\" id=\"nav-new\" data-action=\"new\" title=\"Import company data and run enrichment\">"+icon('spark')+"<span class=\"nav-text\">Data Enrichment</span></button><button class=\"nav-item\" id=\"nav-workspace\" data-action=\"workspace\" title=\"Review your completed enrichment results\">"+icon('database')+"<span class=\"nav-text\">Enriched Companies</span></button>";$('#nav-find').addEventListener('click',()=>$('#nav-find').setAttribute('aria-expanded',$('#nav-find').getAttribute('aria-expanded')==='true'?'false':'true'))}
function directoryRoute(page){if(runTimer){toast('Your enrichment is in progress.');return}const isSaved=page.startsWith('saved-');if(page!=='company'&&page!=='home')discoveryMode=isSaved?'saved':'discover';leadPage=isSaved?page.slice(6):page;document.querySelectorAll('.sidebar .nav-item').forEach(el=>{el.classList.remove('active');el.removeAttribute('aria-current')});const navId=page==='company'?returnDirectory:leadPage;const nav=$('#nav-'+navId);nav?.classList.add('active');nav?.setAttribute('aria-current','page');$('#breadcrumb').textContent=page==='company'?'Company details':page==='home'?'Home':'Find Leads / '+(leadPage==='people'?'People':'Companies');if(page==='home')renderLeadHome();else if(page==='company')renderCompanyProfile();else renderLeadDirectory();window.scrollTo(0,0)}
function filterInput(label,key,placeholder,ico){const value=currentSearch().draft[key];return `<section class="filter-section"><label for="filter-${key}">${icon(ico)}${label}</label><input class="input ${value?'has-value':''}" id="filter-${key}" data-filter-key="${key}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off">${key==='keywords'?`<p class="filter-help">${leadPage==='people'?'Role, skills, or experience keywords':'Company description or business keywords'}</p>`:''}</section>`}
function filterSelect(label,key,options,ico,empty='Any'){const value=currentSearch().draft[key];return `<section class="filter-section"><label for="filter-${key}">${icon(ico)}${label}</label><select class="input ${value?'has-value':''}" id="filter-${key}" data-filter-key="${key}"><option value="">${empty}</option>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`}).join('')}</select></section>`}
/* USER-JOURNEY
 * ADDITIONAL FILTERS: REFINE THE CURRENT SEARCH
 * The user enters company name, location, industry, and keywords to narrow the list.
 * People also allows job title; Companies also allows a company-size range.
 * A Kenya search enables county selection. City or region is optional.
 * After changing preferences, the user selects Apply filters to refresh the results.
 * Clear all removes the current search and refinements. Discover returns to its empty
 * starting point; Saved returns to the user's complete saved shortlist.
 */
function filterPanel(){const s=currentSearch(),f=s.draft;return `<aside class="filter-panel" aria-label="${leadPage==='people'?'People':'Company'} filters"><div class="filter-panel-header"><h2>${icon('filter')}Filters <span class="filter-count" id="filter-draft-count">${filterCount(f)}</span></h2><button class="clear-filters" data-search-action="clear">Clear all</button></div><form id="discovery-filter-form"><div class="filter-body">${filterInput('Company name','company','Enter company or domain','building')}${leadPage==='people'?filterInput('Job title','title','e.g. Procurement Manager','briefcase'):''}<section class="filter-section"><label for="filter-country">${icon('pin')}Location</label><div class="location-filter"><select class="input ${f.country?'has-value':''}" id="filter-country" data-filter-key="country" aria-label="Country"><option value="">Any country</option>${['Kenya','Uganda','Tanzania'].map(c=>`<option ${f.country===c?'selected':''}>${c}</option>`).join('')}</select><select class="input ${f.county?'has-value':''}" id="filter-county" data-filter-key="county" aria-label="County" ${effectiveCountyCountry(f)!=='Kenya'?'disabled':''}><option value="">${effectiveCountyCountry(f)==='Kenya'?'Any county':'County · select Kenya'}</option>${countyOptions(effectiveCountyCountry(f)).map(c=>`<option ${f.county===c?'selected':''}>${c}</option>`).join('')}</select><input class="input ${f.location?'has-value':''}" id="filter-location" data-filter-key="location" aria-label="City or region" placeholder="City or region (optional)" value="${esc(f.location)}"></div><p class="filter-help">${leadPage==='people'?'Where the person is based':'Company headquarters location'}</p></section>${leadPage==='companies'?filterSelect('Company size','size',companySizes,'people','Any employee range'):''}${filterSelect('Industry','industry',['Pharmaceuticals','Medical Distribution','Retail Pharmacies'],'grid','Any industry')}${filterInput('Keywords','keywords','Enter keywords, separated by commas','search')}</div><div class="filter-actions"><p class="filter-validation" id="filter-validation" role="alert">${esc(s.error)}</p><button class="btn primary" type="submit">${icon('search')}Apply filters</button><p class="filter-help">Use at least one filter to start discovery.</p></div></form></aside>`}
/* USER-JOURNEY
 * PEOPLE AND COMPANIES: START, SEARCH, THEN REFINE
 * The user sees the screen title, a prominent search bar, Discover and Saved tabs,
 * additional filters, and an empty results area before their first search.
 * They enter a medicine, product category, country, or a combination and select Search.
 * They can then narrow the results with additional filters and select Apply filters.
 * People offers company, job title, location, industry, and professional keywords.
 * Companies offers company, location, company size, industry, and business keywords.
 */
function renderLeadDirectory(){const people=leadPage==='people',saved=discoveryMode==='saved';const title=people?'People':'Companies';$('#main').innerHTML=`<header class="discovery-heading"><div><h1>${icon(people?'people':'building')}${title}</h1><p>${people?'Find the decision-makers behind your next export opportunity.':'Find pharmaceutical partners that fit your market.'}</p></div><span class="discovery-head-label">${icon('shield')}Pharmaceutical export intelligence</span></header>${quickSearchBar()}<nav class="discovery-tabs" role="tablist" aria-label="${people?'People':'Company'} views"><button class="discovery-tab ${!saved?'active':''}" id="discover-tab" role="tab" aria-controls="discovery-panel" aria-selected="${!saved}" tabindex="${!saved?0:-1}" data-lead-nav="${leadPage}">${icon('search')}Discover</button><button class="discovery-tab ${saved?'active':''}" id="saved-tab" role="tab" aria-controls="discovery-panel" aria-selected="${saved}" tabindex="${saved?0:-1}" data-lead-nav="saved-${leadPage}">${icon('bookmark')}Saved<span class="tab-count" data-saved-tab>${savedEntities[leadPage].length}</span></button></nav><div class="discovery-layout" id="discovery-panel" role="tabpanel" aria-labelledby="${saved?'saved-tab':'discover-tab'}"><!-- FEATURE: additional refinement filters -->${filterPanel()}<div><!-- FEATURE: results remain empty until Search or Apply filters --> <section class="discovery-workspace"><div class="workspace-toolbar"><div><h2 id="workspace-title"></h2><p id="workspace-subtitle"></p></div><div class="workspace-tools"><span class="pending-badge" id="unapplied-badge" hidden>${icon('clock')}Unapplied changes</span><select class="lead-sort" id="discovery-sort" aria-label="Sort results"><option value="relevance">Recommended order</option><option value="name">${people?'Person':'Company'} name A–Z</option>${people?'<option value="company">Company name A–Z</option>':'<option value="size">Largest company first</option>'}</select></div></div><div id="applied-filter-chips"></div><div class="discovery-table-wrap" id="lead-table-wrap"></div><div class="workspace-bottom"><span id="lead-table-count"></span><div class="pagination" id="lead-pagination"></div></div></section><p class="discovery-caption">${icon('info')}Fictional demo data. Contacts, company sizes, industries, and product associations are illustrative. Saved records and requests remain in this browser.</p></div></div>`;$('#discovery-sort').value=currentSearch().sort;renderLeadTable();wireLeadSearch()}
function emptyIllustration(kind){return `<div class="search-illustration" aria-hidden="true"><div class="illustration-orbit"></div><div class="illustration-card"><span>${icon(kind==='people'?'people':'building')}</span><div class="illustration-lines"><i></i><i></i><i></i></div></div><div class="illustration-search">${icon(discoveryMode==='saved'?'bookmark':'search')}</div></div>`}
/* USER-JOURNEY
 * EMPTY RESULTS: UNDERSTAND WHAT TO DO NEXT
 * Before the first search, the user is prompted to search or apply filters.
 * An empty Saved tab explains that they must bookmark a record first.
 * After an unsuccessful search, the user is encouraged to broaden or clear the criteria.
 * An example-search button is an optional starting point the user chooses explicitly.
 */
function emptyWorkspace(state){const kind=leadPage,people=kind==='people';if(state==='initial')return `<div class="discovery-blank">${emptyIllustration(kind)}<h3>${people?'Find people who move business forward.':'Your next partner starts with a search.'}</h3><p>${people?'Search by medicine, product category, or country above. Then refine people by company, job title, location, industry, or keywords.':'Search by medicine, product category, or country above. Use additional filters to narrow your company results.'}</p><div class="empty-example"><span>NEED A STARTING POINT?</span><button class="example-button" data-search-action="example">${icon('spark')}${people?'Find procurement managers in Kenya':'Find pharma companies in Kenya'}${icon('arrow')}</button></div></div>`;if(state==='saved-empty')return `<div class="discovery-blank">${emptyIllustration(kind)}<h3>No saved ${kind} yet.</h3><p>Save ${people?'a person':'a company'} from your search results using the bookmark icon. ${people?'People':'Companies'} you save will appear here.</p><div class="empty-example"><button class="example-button" data-lead-nav="${kind}">${icon('search')}Discover ${kind}${icon('arrow')}</button></div></div>`;return `<div class="discovery-blank">${emptyIllustration(kind)}<h3>No ${kind} match these filters.</h3><p>Try a broader job title, location, or company name${people?'':', or a different company size'}. Results must match every filter group.</p><div class="empty-example"><button class="example-button" data-search-action="clear">Clear filters${icon('arrow')}</button></div></div>`}
/* USER-JOURNEY
 * RESULTS: REVIEW RELEVANT RECORDS
 * After searching, the user sees the result count, applied criteria, and a focused list.
 * They can sort records, move between pages, open profiles, save suitable prospects,
 * or request missing information. Changing pages does not erase their search.
 * If nothing matches, they can broaden or clear the criteria and try again.
 */
function renderLeadTable(){if(!['people','companies'].includes(leadPage)||!$('#lead-table-wrap'))return;const s=currentSearch(),saved=discoveryMode==='saved',records=searchRecords(),started=saved||s.searched,count=records.length,pageSize=7;s.page=Math.min(s.page,Math.max(0,Math.ceil(count/pageSize)-1));const shown=records.slice(s.page*pageSize,(s.page+1)*pageSize);$('#workspace-title').innerHTML=started?`${saved?'Saved '+leadPage:'Search results'} <span class="workspace-count">${count}</span>`:'Your search workspace';$('#workspace-subtitle').textContent=!started?'Apply filters to reveal relevant '+leadPage:saved?(s.searched?'Filtered saved records':'Records you have explicitly saved'):'Matching your applied criteria';const chips=s.searched?activeFilters(s.applied):[];$('#applied-filter-chips').innerHTML=chips.length?`<div class="applied-filters"><span class="label">APPLIED</span>${chips.map(([l,v])=>`<span class="applied-chip"><b>${esc(l)}</b>${esc(v)}</span>`).join('')}</div>`:'';let empty=!started?'initial':saved&&!savedEntities[leadPage].length?'saved-empty':count===0?'no-matches':'';$('#lead-table-wrap').innerHTML=empty?emptyWorkspace(empty):leadPage==='people'?peopleTable(shown):companyTable(shown);$('#lead-table-count').textContent=!started?'No records loaded':count?`${s.page*pageSize+1}–${Math.min((s.page+1)*pageSize,count)} of ${count} ${leadPage}`:saved&&!savedEntities[leadPage].length?'Your saved list is empty':'0 matching records';$('#lead-pagination').innerHTML=Array.from({length:Math.ceil(count/pageSize)},(_,i)=>`<button class="${s.page===i?'active':''}" data-discovery-page="${i}" aria-label="Page ${i+1}" ${s.page===i?'aria-current="page"':''}>${i+1}</button>`).join('');$('#discovery-sort').hidden=!count;updateFilterStatus()}
/* USER-JOURNEY
 * SAVE A PROSPECT: ADD IT TO YOUR SHORTLIST
 * The user selects the bookmark beside a company or person.
 * A selected bookmark shows that the record is saved. Selecting it again removes the save.
 * Saving a company does not automatically save its employees, and saving a person does
 * not automatically save their employer.
 */
function saveControl(kind,id,name){const saved=savedEntities[kind].includes(id);return `<button class="save-toggle ${saved?'saved':''}" data-save-kind="${kind}" data-save-id="${id}" aria-pressed="${saved}" aria-label="${saved?'Remove saved':'Save'} ${kind==='people'?'person':'company'} ${esc(name)}" title="${saved?'Remove from Saved':'Save to '+(kind==='people'?'People':'Companies')}">${icon('bookmark')}</button>`}
/* USER-JOURNEY
 * COMPANIES LIST: COMPARE POTENTIAL BUSINESS PARTNERS
 * The user compares five columns: Company, Business type, Location, Industry and products,
 * and Company contact. Company name includes website, size, and a bookmark.
 * Email and phone are shown when available; missing information offers Request Data.
 * The user clicks a company name for the complete profile rather than seeing more columns.
 */
function companyTable(list){return `<table class="premium-table"><thead><tr><th>Company</th><th>Business type</th><th>Location</th><th>Industry & products</th><th>Company contact</th></tr></thead><tbody>${list.map(c=>`<tr><td><div class="entity-cell"><span class="company-avatar">${esc(initials(c.name))}</span><div class="entity-text"><button class="entity-link" data-open-company="${c.id}">${esc(c.name)}</button><div class="entity-subline">${esc(c.website)||'Website unavailable'}<br>${esc(c.sizeLabel)}</div></div>${saveControl('companies',c.id,c.name)}</div></td><td>${businessBadge(c)}<div class="entity-subline">${c.employees.length} known ${c.employees.length===1?'contact':'contacts'}</div></td><td><div class="location-cell">${esc(c.city)}<small>${esc(c.county?c.county+', '+c.country:c.country)}</small></div></td><td><div style="font-size:10px;margin-bottom:7px">${esc(c.industry)}</div><div class="medicine-tags">${c.medicines.map(m=>`<span class="medicine-tag">${esc(m)}</span>`).join('')}</div></td><td><div class="contact-line ${c.email?'':'missing'}">${icon('mail')}<span class="contact-value" title="${esc(c.email)}">${esc(c.email)||'Email unavailable'}</span></div><div class="contact-line ${c.phone?'':'missing'}">${icon('phone')}<span class="contact-value">${esc(c.phone)||'Phone unavailable'}</span></div>${requestButton(c,null,true)}</td></tr>`).join('')}</tbody></table>`}
/* USER-JOURNEY
 * PEOPLE LIST: FIND THE RIGHT PERSON TO CONTACT
 * The user sees the person's name and role, employer, location, available work contacts,
 * and LinkedIn availability. They can bookmark a person, open their professional profile,
 * open their employer's company profile, or request missing contact information.
 * The company's Employees tab provides the same contact and saving options.
 */
function peopleTable(records){return `<table class="premium-table people"><thead><tr><th>Person & job title</th><th>Company</th><th>Location</th><th>Work contact</th><th>LinkedIn</th></tr></thead><tbody>${records.map(({c,p})=>`<tr><td><div class="entity-cell"><span class="avatar">${esc(initials(p.name))}</span><div class="entity-text"><button class="entity-link" data-person-detail="${p.id}">${esc(p.name)}</button><div class="entity-subline">${esc(p.role)}</div></div>${saveControl('people',p.id,p.name)}</div></td><td><button class="entity-link" data-open-company="${c.id}">${esc(c.name)}</button><div class="entity-subline">${esc(c.industry)}</div></td><td><div class="location-cell">${esc(p.city)}<small>${esc(p.country)}</small></div></td><td><div class="contact-line ${p.email?'':'missing'}">${icon('mail')}<span class="contact-value" title="${esc(p.email)}">${esc(p.email)||'Email unavailable'}</span></div><div class="contact-line ${p.phone?'':'missing'}">${icon('phone')}<span class="contact-value">${esc(p.phone)||'Phone unavailable'}</span></div>${requestButton(c,p,true)}</td><td>${profileLink(p.linkedin,'Profile')}</td></tr>`).join('')}</tbody></table>`}
function updateFilterStatus(){const s=currentSearch();if($('#quick-search'))$('#quick-search').classList.toggle('has-value',!!s.draft.query);$('#filter-draft-count').textContent=filterCount(s.draft);$('#unapplied-badge').hidden=!(filterChanges(s)&&(s.searched||discoveryMode==='saved'));document.querySelectorAll('[data-filter-key]').forEach(el=>el.classList.toggle('has-value',!!el.value))}
/* USER-JOURNEY
 * SEARCH AND APPLY FILTERS: CONFIRM YOUR CRITERIA
 * The user must enter a search or at least one filter before discovering records.
 * Search and Apply filters use the query and refinements together.
 * The list then updates, and applied criteria are shown above it.
 * Unapplied changes means the user has edited criteria but still sees the previous results.
 */
function applyDiscoveryFilters(){const s=currentSearch();if(!filterCount(s.draft)){s.error='Enter a search or add at least one filter.';$('#filter-validation').textContent=s.error;if($('#quick-search-error'))$('#quick-search-error').textContent=s.error;return}s.error='';s.applied={...s.draft};s.searched=true;s.page=0;$('#filter-validation').textContent='';if($('#quick-search-error'))$('#quick-search-error').textContent='';renderLeadTable()}
function wireLeadSearch(){wireQuickSearch();$('#discovery-filter-form').addEventListener('submit',e=>{e.preventDefault();applyDiscoveryFilters()});document.querySelectorAll('[data-filter-key]').forEach(el=>{const update=()=>{const s=currentSearch(),key=el.dataset.filterKey;s.draft[key]=el.value;if(key==='country'){s.draft.county='';syncCountyPicker()}s.error='';$('#filter-validation').textContent='';if($('#quick-search-error'))$('#quick-search-error').textContent='';updateFilterStatus()};el.addEventListener('input',update);if(el.tagName==='SELECT')el.addEventListener('change',update)});$('#discovery-sort').addEventListener('change',e=>{currentSearch().sort=e.target.value;currentSearch().page=0;renderLeadTable()})}
function persistSaved(){try{localStorage.setItem(savedKey,JSON.stringify(savedEntities));savedStorageAvailable=true}catch(e){savedStorageAvailable=false}document.querySelectorAll('[data-saved-count]').forEach(el=>el.textContent=savedEntities[el.dataset.savedCount].length)}
/* USER-JOURNEY
 * SAVED TAB: RETURN TO YOUR CHOSEN PROSPECTS
 * Saved inside Companies contains only companies the user bookmarked.
 * Saved inside People contains only people they bookmarked. There is no separate Saved screen.
 * The user can search and refine their shortlist, inspect profiles, or remove bookmarks.
 * Removing a saved record does not delete it from the discovery directory.
 * In this demo, saved records remain in the same browser when storage is available;
 * otherwise the user is told that the save lasts only for the current session.
 */
function toggleSaved(kind,id){const data=kind==='people'?directory.flatMap(c=>c.employees).find(p=>p.id===id):directory.find(c=>c.id===id);if(!data)return;const had=savedEntities[kind].includes(id);savedEntities[kind]=had?savedEntities[kind].filter(x=>x!==id):[...savedEntities[kind],id];persistSaved();toast((had?'Removed from Saved ':'Saved to ')+(kind==='people'?'People':'Companies')+(savedStorageAvailable?'':' · Session only; browser storage unavailable'));if(['companies','people'].includes(leadPage)){renderLeadTable();const tab=$('[data-saved-tab]');if(tab)tab.textContent=savedEntities[leadPage].length}else if(leadPage==='company')renderCompanyProfile();else if($('#person-save-action'))$('#person-save-action').innerHTML=saveControl(kind,id,data.name)}
function openCompany(id){selectedCompany=id;profileTab='overview';returnDirectory=leadPage==='people'?'people':'companies';returnSaved=discoveryMode==='saved';directoryRoute('company')}
/* USER-JOURNEY: COMPANY DETAILS. The user opens a company to review its business, market, products, contacts, and employees. The Overview and Employees tabs change the detail being shown, and a missing item can be requested from this page. */
function renderCompanyProfile(){const c=directory.find(c=>c.id===selectedCompany);if(!c){directoryRoute('companies');return}const missing=missingCompanyFields(c);$('#main').innerHTML=`<button class="lead-back" data-lead-action="back">${icon('arrow')}Back to ${returnDirectory==='people'?'people':'companies'}</button><section class="company-profile-header"><div class="company-profile-top"><div class="company-profile-identity"><span class="company-avatar">${esc(initials(c.name))}</span><div><div class="lead-eyebrow" style="font-size:9px;margin-bottom:6px">COMPANY INTELLIGENCE</div><h1>${esc(c.name)}</h1><div class="company-profile-meta">${businessBadge(c)}<span>${icon('pin')}${esc(c.city)}, ${esc(c.country)}</span><span>${icon('people')}${c.employees.length} known employees</span></div></div></div><div class="buttons">${requestButton(c)}<span class="tag gray">Demo profile</span></div></div></section><div class="profile-tabs" role="group" aria-label="Company detail sections"><button class="profile-tab ${profileTab==='overview'?'active':''}" data-profile-tab="overview" aria-pressed="${profileTab==='overview'}">Overview</button><button class="profile-tab ${profileTab==='employees'?'active':''}" data-profile-tab="employees" aria-pressed="${profileTab==='employees'}">Employees <span class="tag gray" style="margin-left:5px">${c.employees.length}</span></button></div>${profileTab==='overview'?`<div class="company-profile-grid"><div><section class="panel profile-card"><h2>About this company</h2><p class="profile-description">${esc(c.description)}</p><div class="detail-row" style="margin-top:15px"><span>Business type</span><span>${c.type}</span></div><div class="detail-row"><span>County</span><span>${esc(c.county)||'Not applicable'}</span></div><div class="detail-row"><span>Country</span><span>${c.country}</span></div></section><section class="panel profile-card"><h2>Medicines & product categories</h2><div class="medicine-tags">${c.medicines.map(m=>`<span class="medicine-tag" style="padding:6px 10px;font-size:11px">${m}</span>`).join('')}</div><p class="hint" style="margin-top:14px">Illustrative product associations, not a current stock or regulatory record.</p></section><section class="panel profile-card"><div class="lead-section-heading"><div><h2 style="margin-bottom:4px">People at this company</h2><p>${c.employees.length?'Find the right person for your next conversation.':'Employee information is not yet available.'}</p></div>${c.employees.length?'<button class="btn" data-profile-tab="employees">View employees '+icon('arrow')+'</button>':requestButton(c)}</div>${c.employees.slice(0,2).map(p=>`<div class="profile-contact-row"><div class="avatar">${esc(initials(p.name))}</div><div><p>${esc(p.name)}</p><label style="margin-top:3px">${esc(p.role)}</label></div></div>`).join('')}</section></div><aside><section class="panel profile-card"><h2>Contact information</h2>${companyContact(c,'website','Website','link')}${companyContact(c,'email','Company email','mail')}${companyContact(c,'phone','Company phone','phone')}${companyContact(c,'linkedin','Company LinkedIn','people')}</section><section class="panel profile-card"><h2>Data availability</h2>${[['website','Website'],['email','Company email'],['phone','Company phone'],['linkedin','LinkedIn'],['employees','Employee list']].map(([k,l])=>`<div class="coverage-row"><span>${l}</span>${(k==='employees'?c.employees.length:c[k])?`<span>${icon('check')} Available</span>`:'<span class="missing-status">Missing</span>'}</div>`).join('')}${missing.length?`<p class="hint" style="margin:15px 0">Request the missing information in one step.</p>${requestButton(c)}`:''}</section></aside></div>`:`<section class="panel"><div class="panel-header"><div><h2>Employees at ${esc(c.name)}</h2><p>Professional contact information · Fictional demo profiles</p></div></div><div class="table-scroll">${c.employees.length?employeeDetailTable(c):`<div class="lead-empty"><div class="file-icon">${icon('people')}</div><h2>Employee data is not available</h2><p>Request an employee list for this company.</p>${requestButton(c)}</div>`}</div></section>`}<div class="lead-demo-note">${icon('info')}<span>This is a fictional company profile. Website/email domains use .example and LinkedIn profiles are illustrative. No information has been verified against live sources.</span></div>${footer()}`}
const renderOriginalCompanyProfile=renderCompanyProfile;
renderCompanyProfile=function(){renderOriginalCompanyProfile();const c=directory.find(c=>c.id===selectedCompany);if(!c)return;$('.company-profile-top>.buttons')?.insertAdjacentHTML('afterbegin',`<button class="btn details-save-button ${savedEntities.companies.includes(c.id)?'primary':''}" data-save-kind="companies" data-save-id="${c.id}" aria-pressed="${savedEntities.companies.includes(c.id)}">${icon('bookmark')}${savedEntities.companies.includes(c.id)?'Saved company':'Save company'}</button>`);$('.company-profile-meta')?.insertAdjacentHTML('beforeend',`<span>${icon('people')}${esc(c.sizeLabel)}</span><span>${icon('grid')}${esc(c.industry)}</span>`)};
/* USER-JOURNEY
 * PERSON PROFILE: REVIEW A BUSINESS CONTACT
 * The user reviews the person's current role, employer, location, industry, skills,
 * available email, phone, and LinkedIn information.
 * They can save the person or request missing contact information, then close the profile
 * and continue reviewing their list. All displayed profiles in this demo are fictional.
 */
function openPersonDetails(id){const c=directory.find(c=>c.employees.some(p=>p.id===id)),p=c?.employees.find(p=>p.id===id);if(!p)return;openLeadModal(modalHeader('Person details')+`<div class="lead-modal-body person-profile-modal"><div class="employee-name"><span class="avatar" style="width:44px;height:44px;font-size:14px">${esc(initials(p.name))}</span><div><h3 style="margin:0">${esc(p.name)}</h3><p class="muted" style="font-size:11px">${esc(p.role)}</p></div><span id="person-save-action" style="margin-left:auto">${saveControl('people',p.id,p.name)}</span></div><div style="margin:22px 0">${[['Company',c.name],['Location',p.city+', '+p.country],['Industry',c.industry],['Email',p.email||'Not available'],['Phone',p.phone||'Not available'],['Skills',p.skills]].map(([l,v])=>`<div class="detail-row"><span>${l}</span><span>${esc(v)}</span></div>`).join('')}</div>${profileLink(p.linkedin,'LinkedIn profile')}<div class="info-line">${icon('info')}Fictional professional profile. Contact values are demonstration data.</div></div><div class="panel-footer">${requestButton(c,p)}<button class="btn" data-lead-action="close-modal">Close</button></div>`)}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save-kind]');if(save){e.preventDefault();e.stopImmediatePropagation();toggleSaved(save.dataset.saveKind,save.dataset.saveId);if($('#lead-modal').open){const id=save.dataset.saveId,p=directory.flatMap(c=>c.employees).find(p=>p.id===id);if(p&&$('#person-save-action'))$('#person-save-action').innerHTML=saveControl('people',id,p.name)}return}const person=e.target.closest('[data-person-detail]');if(person){e.stopImmediatePropagation();openPersonDetails(person.dataset.personDetail);return}const paging=e.target.closest('[data-discovery-page]');if(paging){e.stopImmediatePropagation();currentSearch().page=Number(paging.dataset.discoveryPage);renderLeadTable();return}const action=e.target.closest('[data-search-action]')?.dataset.searchAction;if(action){e.stopImmediatePropagation();if(action==='clear'){const s=currentSearch();s.draft=filterDefaults();s.applied=filterDefaults();s.searched=false;s.error='';s.page=0;renderLeadDirectory()}if(action==='example'){const s=currentSearch();s.draft=filterDefaults();s.draft.country='Kenya';if(leadPage==='people')s.draft.title='Procurement Manager';else{s.draft.query='Paracetamol, antimalarial drugs';s.draft.industry='Pharmaceuticals'}s.applied={...s.draft};s.searched=true;s.page=0;s.error='';renderLeadDirectory()}return}if(e.target.closest('[data-lead-action="back"]')){e.stopImmediatePropagation();directoryRoute((returnSaved?'saved-':'')+returnDirectory)}},true);
function employeeDetailTable(c){return peopleTable(c.employees.map(p=>({c,p})))}

document.addEventListener('keydown',e=>{if(!e.target.matches('.discovery-tab')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const toSaved=e.key==='End'||e.key!=='Home'&&discoveryMode!=='saved';directoryRoute((toSaved?'saved-':'')+leadPage);document.querySelector(toSaved?'#saved-tab':'#discover-tab')?.focus()});
